// Pure slot-allocation logic for evergreen batch scheduling.
// All scheduling is in Eastern Time (America/New_York), automatically
// handling EST/EDT transitions.

export interface SlotPlan {
  hour: number;
  minute: number;
}

export const DEFAULT_SLOT_PLAN: SlotPlan[] = [
  { hour: 10, minute: 0 },
  { hour: 13, minute: 30 },
];

const TZ = "America/New_York";
const MAX_LOOKAHEAD_DAYS = 365;

interface EtDateParts {
  year: number;
  month: number;
  day: number;
  weekday: number; // 0 = Sun, 6 = Sat
}

function getEtDateParts(date: Date): EtDateParts {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: TZ,
    year: "numeric",
    month: "numeric",
    day: "numeric",
    weekday: "short",
  });
  const parts = fmt.formatToParts(date);
  const get = (type: string) =>
    parts.find((p) => p.type === type)?.value || "";
  const weekdayMap: Record<string, number> = {
    Sun: 0,
    Mon: 1,
    Tue: 2,
    Wed: 3,
    Thu: 4,
    Fri: 5,
    Sat: 6,
  };
  return {
    year: parseInt(get("year"), 10),
    month: parseInt(get("month"), 10),
    day: parseInt(get("day"), 10),
    weekday: weekdayMap[get("weekday")],
  };
}

function getEtOffsetMinutes(utcDate: Date): number {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: TZ,
    timeZoneName: "longOffset",
  });
  const tzName =
    fmt
      .formatToParts(utcDate)
      .find((p) => p.type === "timeZoneName")?.value || "";
  const match = tzName.match(/GMT([+-])(\d{2}):(\d{2})/);
  if (!match) return -300;
  const sign = match[1] === "+" ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const mins = parseInt(match[3], 10);
  return sign * (hours * 60 + mins);
}

// Converts an ET wall-clock moment to an ISO 8601 string with the correct
// ET offset (EST or EDT). Slot times of interest (10:00, 13:30) are well
// clear of the 2am DST transition, so single-pass offset resolution is
// sufficient.
export function etWallClockToIso(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
): string {
  const candidate = new Date(Date.UTC(year, month - 1, day, hour, minute));
  const offset = getEtOffsetMinutes(candidate);
  const offsetHours = Math.floor(Math.abs(offset) / 60);
  const offsetMins = Math.abs(offset) % 60;
  const offsetSign = offset >= 0 ? "+" : "-";
  const offsetStr = `${offsetSign}${String(offsetHours).padStart(2, "0")}:${String(offsetMins).padStart(2, "0")}`;
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${year}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}:00${offsetStr}`;
}

function addDaysEt(parts: EtDateParts, days: number): EtDateParts {
  // Use UTC date arithmetic to advance day count, then re-derive ET parts
  // from a noon-UTC anchor (noon avoids any DST edge cases).
  const utc = new Date(
    Date.UTC(parts.year, parts.month - 1, parts.day + days, 12, 0, 0),
  );
  return getEtDateParts(utc);
}

// Find the next available slot at or after `now`, skipping weekends and
// any slot already in `usedSlots`. Returns an ISO 8601 string with the
// correct ET offset.
export function findNextSlot(
  now: Date,
  usedSlots: string[],
  plan: SlotPlan[] = DEFAULT_SLOT_PLAN,
): string {
  // Compare as instants so that ET-offset strings and UTC-Z strings
  // representing the same moment both register as "used".
  const usedInstants = new Set(
    usedSlots
      .map((s) => new Date(s).getTime())
      .filter((n) => !Number.isNaN(n)),
  );
  const nowMs = now.getTime();
  let parts = getEtDateParts(now);

  for (let i = 0; i < MAX_LOOKAHEAD_DAYS; i++) {
    const isWeekend = parts.weekday === 0 || parts.weekday === 6;
    if (!isWeekend) {
      for (const slot of plan) {
        const iso = etWallClockToIso(
          parts.year,
          parts.month,
          parts.day,
          slot.hour,
          slot.minute,
        );
        const instant = new Date(iso).getTime();
        if (usedInstants.has(instant)) continue;
        if (instant <= nowMs) continue;
        return iso;
      }
    }
    parts = addDaysEt(parts, 1);
  }

  throw new Error(
    `Could not find an available slot within ${MAX_LOOKAHEAD_DAYS} days`,
  );
}

