// Calendar audit: keep the curated reshare queue honest against live content.
//
// The queue (agile-pain-relief-astro/social-media/planning/
// complete-social-media-calendar.md) is hand-curated, so it drifts: posts get
// renamed or retired (dead links), and new posts land that were never added.
// This script diffs the queue against the live blog/glossary collections,
// reports the gaps, and (with --write) refreshes the header counts.
//
// Read-only by default. Pass --write to update the calendar header block.
// Pass --verbose to list every unlisted slug, not just a sample.
//
// Curation stays manual: this never adds, removes, or checks off queue items.

import * as fs from "fs";
import * as path from "path";
import { fileURLToPath } from "url";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const ASTRO_REPO = path.resolve(scriptDir, "..", "..", "agile-pain-relief-astro");
const CALENDAR = path.join(
  ASTRO_REPO,
  "social-media",
  "planning",
  "complete-social-media-calendar.md",
);
const BLOG_DIR = path.join(ASTRO_REPO, "src", "content", "blog");
const GLOSSARY_DIR = path.join(ASTRO_REPO, "src", "content", "glossary");

const WRITE = process.argv.includes("--write");
const VERBOSE = process.argv.includes("--verbose");

// Posting consumes ~1 calendar item per weekday (2 of the 3 daily posts are
// quiz hooks, not calendar items), so the queue drains ~5 items/week.
const ITEMS_PER_WEEK = 5;

function fail(msg) {
  console.error(`calendar-audit: ${msg}`);
  process.exit(1);
}

function liveSlugs(dir) {
  if (!fs.existsSync(dir)) fail(`content dir not found: ${dir}`);
  return new Set(
    fs
      .readdirSync(dir, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name),
  );
}

// Parse the queue: every `- [ ]` / `- [x]` line that references a blog or
// glossary URL is one queue item. Returns { blog, glossary } slug sets plus
// posted/total counts.
function parseQueue(markdown) {
  const blog = new Set();
  const glossary = new Set();
  let total = 0;
  let posted = 0;
  const checkbox = /^\s*-\s*\[( |x|X)\]\s*(.*)$/;
  const link = /agilepainrelief\.com\/(blog|glossary)\/([a-z0-9_-]+)/i;
  for (const line of markdown.split("\n")) {
    const m = checkbox.exec(line);
    if (!m) continue;
    const l = link.exec(m[2]);
    if (!l) continue;
    total += 1;
    if (m[1].toLowerCase() === "x") posted += 1;
    (l[1].toLowerCase() === "blog" ? blog : glossary).add(l[2]);
  }
  return { blog, glossary, total, posted };
}

const diff = (a, b) => [...a].filter((x) => !b.has(x)).sort();

function buildHeader(stats, today) {
  const {
    queue,
    liveBlog,
    liveGlossary,
    deadBlog,
    deadGlossary,
    unlistedBlog,
    unlistedGlossary,
  } = stats;
  const remaining = queue.total - queue.posted;
  const weeks = Math.round(remaining / ITEMS_PER_WEEK);
  const liveTotal = liveBlog.size + liveGlossary.size;
  return [
    `**Curated reshare queue:** ${queue.total} items (${queue.blog.size} blog + ${queue.glossary.size} glossary). ${queue.posted} posted, ${remaining} remaining.`,
    `**Live site inventory:** ${liveBlog.size} blog + ${liveGlossary.size} glossary = ${liveTotal} published.`,
    `**Not yet in the queue:** ${unlistedBlog.length} blog + ${unlistedGlossary.length} glossary (curate in as wanted).`,
    `**Dead queue links (post no longer on site):** ${deadBlog.length + deadGlossary.length}.`,
    `**Cadence:** 3 posts/weekday (2 quiz + 1 calendar item); the queue drains about ${ITEMS_PER_WEEK} items/week.`,
    `**Runway:** about ${weeks} weeks of calendar items at that cadence.`,
    `**Last audited:** ${today}. Run \`npm run calendar-audit\` to refresh.`,
  ];
}

function writeHeader(markdown, headerLines) {
  const lines = markdown.split("\n");
  const h1 = lines.findIndex((l) => l.startsWith("# "));
  if (h1 === -1) fail("no H1 heading found in calendar");
  let sep = -1;
  for (let i = h1 + 1; i < lines.length; i++) {
    if (lines[i].trim() === "---") {
      sep = i;
      break;
    }
  }
  if (sep === -1) fail("no `---` separator found after the H1");
  const out = [
    ...lines.slice(0, h1 + 1),
    "",
    ...headerLines,
    "",
    ...lines.slice(sep),
  ];
  fs.writeFileSync(CALENDAR, out.join("\n"), "utf-8");
}

function printList(label, items) {
  if (items.length === 0) {
    console.log(`  ${label}: none`);
    return;
  }
  const shown = VERBOSE ? items : items.slice(0, 15);
  console.log(`  ${label} (${items.length}):`);
  for (const s of shown) console.log(`    - ${s}`);
  if (!VERBOSE && items.length > shown.length) {
    console.log(`    ... and ${items.length - shown.length} more (--verbose to list all)`);
  }
}

function main() {
  if (!fs.existsSync(CALENDAR)) fail(`calendar not found: ${CALENDAR}`);
  const markdown = fs.readFileSync(CALENDAR, "utf-8");
  const queue = parseQueue(markdown);
  const liveBlog = liveSlugs(BLOG_DIR);
  const liveGlossary = liveSlugs(GLOSSARY_DIR);

  const stats = {
    queue,
    liveBlog,
    liveGlossary,
    deadBlog: diff(queue.blog, liveBlog),
    deadGlossary: diff(queue.glossary, liveGlossary),
    unlistedBlog: diff(liveBlog, queue.blog),
    unlistedGlossary: diff(liveGlossary, queue.glossary),
  };

  const remaining = queue.total - queue.posted;
  console.log("=".repeat(60));
  console.log("Social media calendar audit");
  console.log("=".repeat(60));
  console.log(
    `Queue: ${queue.total} items (${queue.blog.size} blog + ${queue.glossary.size} glossary), ${queue.posted} posted, ${remaining} remaining`,
  );
  console.log(
    `Live:  ${liveBlog.size} blog + ${liveGlossary.size} glossary published\n`,
  );

  console.log("Dead queue links (in the queue, no longer on the site):");
  printList("blog", stats.deadBlog);
  printList("glossary", stats.deadGlossary);

  console.log("\nLive but not in the queue (curation candidates):");
  printList("blog", stats.unlistedBlog);
  printList("glossary", stats.unlistedGlossary);

  if (WRITE) {
    const today = new Date().toISOString().slice(0, 10);
    writeHeader(markdown, buildHeader(stats, today));
    console.log(`\nHeader rewritten in ${path.relative(process.cwd(), CALENDAR)}.`);
  } else {
    console.log("\n(report only — pass --write to refresh the calendar header)");
  }
}

main();

