import { describe, it, expect } from "vitest";
import {
  findNextSlot,
  etWallClockToIso,
  DEFAULT_SLOT_PLAN,
} from "./slotAllocator";

// "now" values are constructed in UTC; the allocator interprets them in ET.
// June = EDT (UTC-4), January = EST (UTC-5).

describe("etWallClockToIso", () => {
  it("returns -04:00 offset during EDT (June)", () => {
    expect(etWallClockToIso(2026, 6, 1, 10, 0)).toBe(
      "2026-06-01T10:00:00-04:00",
    );
  });

  it("returns -05:00 offset during EST (January)", () => {
    expect(etWallClockToIso(2026, 1, 5, 10, 0)).toBe(
      "2026-01-05T10:00:00-05:00",
    );
  });

  it("returns -04:00 the day after spring DST start (2026-03-08)", () => {
    expect(etWallClockToIso(2026, 3, 9, 10, 0)).toBe(
      "2026-03-09T10:00:00-04:00",
    );
  });

  it("returns -05:00 the day after fall DST end (2026-11-01)", () => {
    expect(etWallClockToIso(2026, 11, 2, 10, 0)).toBe(
      "2026-11-02T10:00:00-05:00",
    );
  });

  it("formats 13:30 correctly", () => {
    expect(etWallClockToIso(2026, 6, 1, 13, 30)).toBe(
      "2026-06-01T13:30:00-04:00",
    );
  });
});

describe("findNextSlot", () => {
  it("returns today's 10:00 ET when called before 10:00 on a weekday", () => {
    // Monday June 1 2026, 08:00 ET (= 12:00 UTC during EDT)
    const now = new Date("2026-06-01T12:00:00Z");
    expect(findNextSlot(now, [])).toBe("2026-06-01T10:00:00-04:00");
  });

  it("returns today's 13:30 ET when called between 10:00 and 13:30", () => {
    // Monday June 1 2026, 11:00 ET (= 15:00 UTC during EDT)
    const now = new Date("2026-06-01T15:00:00Z");
    expect(findNextSlot(now, [])).toBe("2026-06-01T13:30:00-04:00");
  });

  it("returns next weekday's 10:00 ET when called after 13:30", () => {
    // Monday June 1 2026, 15:00 ET (= 19:00 UTC during EDT)
    const now = new Date("2026-06-01T19:00:00Z");
    expect(findNextSlot(now, [])).toBe("2026-06-02T10:00:00-04:00");
  });

  it("skips Saturday and Sunday", () => {
    // Friday June 5 2026, 17:00 ET — all Friday slots passed
    const now = new Date("2026-06-05T21:00:00Z");
    expect(findNextSlot(now, [])).toBe("2026-06-08T10:00:00-04:00");
  });

  it("skips a slot listed as used", () => {
    // Monday June 1 2026, 08:00 ET — but 10:00 already taken
    const now = new Date("2026-06-01T12:00:00Z");
    const used = ["2026-06-01T10:00:00-04:00"];
    expect(findNextSlot(now, used)).toBe("2026-06-01T13:30:00-04:00");
  });

  it("rolls to next day when all today's slots are used", () => {
    const now = new Date("2026-06-01T12:00:00Z");
    const used = [
      "2026-06-01T10:00:00-04:00",
      "2026-06-01T13:30:00-04:00",
    ];
    expect(findNextSlot(now, used)).toBe("2026-06-02T10:00:00-04:00");
  });

  it("rolls across the weekend when Friday is fully used", () => {
    // Friday June 5 2026, 06:00 ET
    const now = new Date("2026-06-05T10:00:00Z");
    const used = [
      "2026-06-05T10:00:00-04:00",
      "2026-06-05T13:30:00-04:00",
    ];
    expect(findNextSlot(now, used)).toBe("2026-06-08T10:00:00-04:00");
  });

  it("crosses the EDT → EST boundary (Nov 2026)", () => {
    // Friday Oct 30 2026, 16:00 ET — past both slots, Oct 30 is still EDT
    const now = new Date("2026-10-30T20:00:00Z");
    // Next slot is Monday Nov 2 — first weekday after the Nov 1 transition
    expect(findNextSlot(now, [])).toBe("2026-11-02T10:00:00-05:00");
  });

  it("crosses the EST → EDT boundary (March 2026)", () => {
    // Friday March 6 2026, 16:00 ET — past both slots, still EST
    const now = new Date("2026-03-06T21:00:00Z");
    // Next slot is Monday March 9 — first weekday after the March 8 transition
    expect(findNextSlot(now, [])).toBe("2026-03-09T10:00:00-04:00");
  });

  it("supports a custom slot plan", () => {
    const now = new Date("2026-06-01T12:00:00Z");
    const custom = [{ hour: 9, minute: 0 }];
    expect(findNextSlot(now, [], custom)).toBe(
      "2026-06-01T09:00:00-04:00",
    );
  });

  it("treats UTC-Z and ET-offset strings of the same instant as equal", () => {
    // 2026-06-01T10:00:00-04:00 == 2026-06-01T14:00:00Z (same moment)
    const now = new Date("2026-06-01T12:00:00Z");
    expect(findNextSlot(now, ["2026-06-01T14:00:00Z"])).toBe(
      "2026-06-01T13:30:00-04:00",
    );
  });

  it("DEFAULT_SLOT_PLAN is 10:00 and 13:30", () => {
    expect(DEFAULT_SLOT_PLAN).toEqual([
      { hour: 10, minute: 0 },
      { hour: 13, minute: 30 },
    ]);
  });
});

