// Calendar audit: keep the curated reshare queue honest against live content.
//
// The queue (agile-pain-relief-astro/social-media/planning/
// complete-social-media-calendar.md) is hand-curated, so it drifts: posts get
// renamed or retired (dead links), and new posts land that were never added.
// This script diffs the queue against the live blog/glossary collections,
// reports the gaps, and (with --write) refreshes the header counts.
//
// Read-only by default. Pass --write to update the calendar header block.
// Pass --verbose to list every unlisted slug, not just a sample.
//
// Curation stays manual: this never adds, removes, or checks off queue items.

import * as fs from "fs";
import * as path from "path";
import { fileURLToPath } from "url";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const ASTRO_REPO = path.resolve(scriptDir, "..", "..", "agile-pain-relief-astro");
const CALENDAR = path.join(
  ASTRO_REPO,
  "social-media",
  "planning",
  "complete-social-media-calendar.md",
);
const BLOG_DIR = path.join(ASTRO_REPO, "src", "content", "blog");
const GLOSSARY_DIR = path.join(ASTRO_REPO, "src", "content", "glossary");

const WRITE = process.argv.includes("--write");
const VERBOSE = process.argv.includes("--verbose");

// Posting consumes ~1 calendar item per weekday (2 of the 3 daily posts are
// quiz hooks, not calendar items), so the queue drains ~5 items/week.
const ITEMS_PER_WEEK = 5;

function fail(msg) {
  console.error(`calendar-audit: ${msg}`);
  process.exit(1);
}

function liveSlugs(dir) {
  if (!fs.existsSync(dir)) fail(`content dir not found: ${dir}`);
  return new Set(
    fs
      .readdirSync(dir, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name),
  );
}

// Parse the queue: every `- [ ]` / `- [x]` line that references a blog or
// glossary URL is one queue item. Returns { blog, glossary } slug sets plus
// posted/total counts.
function parseQueue(markdown) {
  const blog = new Set();
